"""Copy the runtime core into an empty development folder; never move files."""
from pathlib import Path
import hashlib
import os
import shutil


def ordinary(path):
    if path.is_symlink() or path.is_junction():
        raise ValueError("Linked path")


def digest(path):
    return hashlib.sha256(path.read_bytes()).hexdigest()


def copy_core(source, destination):
    source, destination = Path(source), Path(destination)
    for path in (source, destination):
        for parent in (path, *path.parents):
            ordinary(parent)
    source, destination = source.resolve(), destination.resolve()
    if source == destination or source in destination.parents or destination in source.parents:
        raise ValueError("Overlapping folders")
    if not destination.is_dir() or any(destination.iterdir()):
        raise ValueError("Destination must exist and be empty")
    files = []
    required = (
        "main.py", "packaged_desktop.py", "requirements.txt",
        "requirements-browser.txt", "pyproject.toml",
        "tests/fixtures/synthetic-soapui.xml",
    )
    for name in required:
        path = source / name
        if not path.is_file():
            raise ValueError("Required file absent")
        files.append(path)
    for folder, suffix in (
        ("app_health_checker", ".py"),
        ("mock_server", ".py"),
        ("config/applications", ".json"),
    ):
        root = source / folder
        if not root.is_dir():
            raise ValueError("Required folder absent")
        count = 0
        for current, dirs, names in os.walk(root, followlinks=False):
            ordinary(Path(current))
            dirs[:] = [d for d in dirs if d != "__pycache__"]
            for directory in dirs:
                ordinary(Path(current) / directory)
            for name in names:
                path = Path(current) / name
                if path.suffix.lower() == suffix:
                    ordinary(path)
                    files.append(path)
                    count += 1
        if not count:
            raise ValueError("Required folder empty")
    for name in ("config/example_checks.json", "config/mock_checks.json",
                 "config/local_overrides.example.json"):
        if (source / name).is_file():
            files.append(source / name)
    for path in source.iterdir():
        if path.is_file() and path.name.upper().split('.')[0] in {
            "LICENSE", "LICENCE", "NOTICE", "COPYING", "AUTHORS"
        }:
            files.append(path)
    for path in files:
        for parent in (path, *path.parents):
            ordinary(parent)
    before = {p.relative_to(source): digest(p) for p in files}
    for relative in before:
        target = destination / relative
        target.parent.mkdir(parents=True, exist_ok=True)
        with target.open("xb") as output, (source / relative).open("rb") as incoming:
            shutil.copyfileobj(incoming, output)
    for relative, expected in before.items():
        if digest(source / relative) != expected or digest(destination / relative) != expected:
            raise ValueError("Verification mismatch")
    return len(before)


def main():
    source = Path(__file__).absolute().parent
    destination = source.parent / "Development" / "AppHealthChecker"
    try:
        count = copy_core(source, destination)
    except Exception as exc:
        print("COPY STOPPED:", type(exc).__name__)
        print("Do not retry or delete anything; report this status.")
        return
    print("CORE COPY: PASS")
    print("FILES VERIFIED:", count)
    print("SOURCE FILES: UNCHANGED")
    print("SETTINGS / HISTORY / PRIVATE RESOURCES: NOT COPIED")


if __name__ == "__main__":
    main()
